import React, { useMemo } from 'react';
import { View, type StyleProp, type ViewStyle } from 'react-native';
import LottieView from 'lottie-react-native';
import { useReducedMotion } from 'react-native-reanimated';
import { useLoopsActive } from '../effects/useLoopsActive';

/**
 * EYEGO'S LOTTIE MOMENTS — the Yango layer (device recording 2026-10-30).
 *
 * Eight shape-only animations, 60 fps, generated by scripts/lottie-gen.py and
 * checked frame-by-frame in lottie-web before they were committed. Every
 * brand-coloured shape lives under the keypath "accent", so `color` re-tints
 * them (Economy green, Comfort blue, Premium gold) without a second file.
 *
 * Loops pause when the app is backgrounded or the screen is covered (the
 * same gate every withRepeat uses — RN perf rules); one-shots play once.
 * Reduce Motion shows the finished frame of a one-shot and a still loop.
 */
const SOURCES = {
  searching_radar: require('../lottie/searching_radar.json'),
  bus_found: require('../lottie/bus_found.json'),
  seat_booked_confetti: require('../lottie/seat_booked_confetti.json'),
  boarded: require('../lottie/boarded.json'),
  trip_complete: require('../lottie/trip_complete.json'),
  loading: require('../lottie/loading.json'),
  walk_to_stop: require('../lottie/walk_to_stop.json'),
  ride_card_empty: require('../lottie/ride_card_empty.json'),
} as const;

export type LottieMomentName = keyof typeof SOURCES;

const LOOPS: ReadonlySet<LottieMomentName> = new Set(['searching_radar', 'loading', 'walk_to_stop', 'ride_card_empty']);

export interface LottieMomentProps {
  name: LottieMomentName;
  /** Width in pt; height follows the file's own aspect ratio unless `height` is given. */
  size: number;
  height?: number;
  /** Re-tints every "accent" shape. Omit to keep brand green. */
  color?: string;
  /** Playback speed, 1 = as authored. */
  speed?: number;
  style?: StyleProp<ViewStyle>;
  onFinish?: () => void;
}

const ASPECT: Record<LottieMomentName, number> = {
  searching_radar: 1,
  bus_found: 1,
  seat_booked_confetti: 1,
  boarded: 1,
  trip_complete: 1,
  loading: 1,
  walk_to_stop: 80 / 240,
  ride_card_empty: 300 / 400,
};

export function LottieMoment({ name, size, height, color, speed = 1, style, onFinish }: LottieMomentProps) {
  const loop = LOOPS.has(name);
  // A loader IS the message: it keeps moving under Reduce Motion (a frozen
  // loader reads as "hung"), like Loader does. Everything else is decoration.
  const essential = name === 'loading';
  const reduce = useReducedMotion() && !essential;
  const active = useLoopsActive({ decorative: !essential });
  const filters = useMemo(() => (color ? [{ keypath: 'accent', color }] : undefined), [color]);
  const playing = !reduce && (!loop || active);
  const box = { width: size, height: height ?? size * ASPECT[name] };
  return (
    <View pointerEvents="none" style={[box, style]}>
    <LottieView
      source={SOURCES[name]}
      autoPlay={playing}
      loop={loop}
      speed={speed}
      // Reduced motion: a one-shot shows its finished frame, a loop holds still.
      progress={reduce ? (loop ? 0 : 1) : undefined}
      colorFilters={filters}
      onAnimationFinish={onFinish ? () => onFinish() : undefined}
      resizeMode="contain"
      style={box}
    />
    </View>
  );
}
